import { useEffect, useRef, useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import Menu from './components/Menu';
import Faq from './components/Faq';

// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-[#faf6f0]", "surface": "bg-white", "surface_2": "bg-[#f3ece2]", "heading_text": "text-stone-900", "body_text": "text-stone-600", "muted_text": "text-stone-500", "primary": "bg-amber-800", "primary_hover": "hover:bg-amber-900", "on_primary": "text-amber-50", "border": "border-stone-200", "accent_text": "text-amber-800", "accent_bg": "bg-amber-100", "gradient": "from-amber-700 to-amber-800"};
const RADIUS = "rounded-2xl";
const GRAD = "bg-gradient-to-br from-amber-700 to-orange-800";
const FONT_CSS = ".font-display{font-family: 'Playfair Display', Georgia, serif;} .font-body{font-family: 'Inter', system-ui, sans-serif;} body{font-family: 'Inter', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div ref={ref} className={`reveal ${visible ? 'reveal-visible' : ''}`}>{children}</div>
  );
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: "Menu", href: "#menu" },
    { label: "FAQ", href: "#faq" },
  ];
  return (
    <div className={`min-h-screen ${tw.page_bg} ${tw.heading_text} font-body`}>
      <style>{FONT_CSS}</style>
      <header className={`sticky top-0 z-50 backdrop-blur-xl border-b ${tw.page_bg} ${tw.border}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            {LOGO_URL ? (
              <img src="" alt="Casa Verde" className="h-9 w-auto" />
            ) : (
              <span className={`w-9 h-9 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-sm tracking-tight ${RADIUS}`}>CV</span>
            )}
            <span className="font-display font-extrabold text-lg tracking-tight">Casa Verde</span>
          </a>
          <nav className={`hidden md:flex items-center gap-8 text-sm font-medium ${tw.body_text}`}>
            {links.map(l => <a key={l.href} href={l.href} className="hover:opacity-70 transition-opacity">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#top" className={`px-4 py-2 ${tw.primary} ${tw.primary_hover} ${tw.on_primary} text-sm font-semibold ${RADIUS} transition-colors`}>Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <MenuIcon className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className={`md:hidden border-t px-6 py-4 space-y-3 ${tw.surface} ${tw.border}`}>
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className={`block font-medium ${tw.body_text}`}>{l.label}</a>)}
            <a href="#top" className={`block text-center px-4 py-2.5 ${tw.primary} ${tw.on_primary} font-semibold ${RADIUS}`}>Get started</a>
          </div>
        )}
      </header>
      <main id="top">
      <Reveal><Menu /></Reveal>
      <Reveal><Faq /></Reveal>
      </main>
      <footer className={`border-t py-10 text-center text-sm ${tw.border} ${tw.muted_text}`}>
        <div className="flex items-center justify-center gap-2 mb-2">
          {LOGO_URL ? (
            <img src="" alt="Casa Verde" className="h-7 w-auto" />
          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>CV</span>
          )}
          <span className="font-display font-bold">Casa Verde</span>
        </div>
        &copy; 2026 Casa Verde. All rights reserved.
      </footer>
    </div>    );
}

import React, { useState } from 'react';
import { ChevronDown, ChevronRight, Sparkles } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    question: "Are your pizzas wood-fired?",
    answer:
      "Absolutely! Our wood-fired ovens are a centerpiece of our restaurant, cooking each pie to perfection with just the right balance of smokiness and crust.",
  },
  {
    id: 2,
    question: "Do you offer gluten-free options?",
    answer: "Yes, we have several gluten-free pizzas and pasta dishes. Please inform your server at the time of ordering.",
  },
  {
    id: 3,
    question: "Is there a dress code?",
    answer:
      "We embrace a sophisticated yet relaxed vibe. Think stylish casual with an emphasis on comfort and style.",
  },
  {
    id: 4,
    question: "How is your wine sourced?",
    answer:
      "Our sommelier has curated an extensive list of natural wines from small producers around the globe, ensuring authentic flavors and sustainable sourcing.",
  },
  {
    id: 5,
    question: "Can I bring my pet?",
    answer:
      "We believe that enjoying great food should be a family affair! Pets are welcome in our outdoor seating area with a small fee.",
  },
];

export default function Faq() {
  const [isOpen, setIsOpen] = useState(false);

  const toggleAccordion = (id) => {
    setIsOpen((prevOpen) => {
      const newOpen = { ...prevOpen, [id]: !prevOpen[id] };
      if (Object.values(newOpen).filter((val) => val).length > 2) {
        return { [id]: false };
      }
      return newOpen;
    });
  };

  return (
    <div className="w-full bg-white/5 p-8 sm:p-12 lg:p-16 max-w-7xl mx-auto rounded-2xl shadow-2xl shadow-amber-500/50 backdrop-blur-xl">
      <div className="relative mb-12 sm:mb-16 text-center">
        <h2 className="text-2xl sm:text-3xl font-bold text-stone-100 tracking-tight mb-4">
          <span className="inline-block bg-gradient-to-br from-amber-700 to-orange-800 bg-clip-text text-transparent">
            Frequently Asked Questions
          </span>
        </h2>
        <p className="text-stone-400 max-w-md mx-auto">
          Explore the details that make Casa Verde an unforgettable dining experience.
        </p>
        <div className="h-1 w-20 bg-white/10 rounded-full mt-8 mb-12 border border-stone-200" />
      </div>

      <div className="space-y-8 sm:space-y-10">
        {faqItems.map((item) => (
          <div
            key={item.id}
            className="group relative border border-stone-200 rounded-2xl p-6 hover:scale-[1.02] transition-transform duration-300 hover:border-stone-200 hover:shadow-2xl"
          >
            <div className="flex justify-between items-start mb-4">
              <h3 className="text-lg font-semibold text-stone-300 flex-1 group-hover:text-amber-400 transition-colors duration-300">
                {item.question}
                <span className="inline-flex items-center gap-1.5 text-stone-400">
                  {isOpen[item.id] ? (
                    <ChevronRight className="w-4 h-4 text-stone-500 animate-bounce" />
                  ) : (
                    <ChevronDown className="w-4 h-4 text-stone-500" />
                  )}
                </span>
              </h3>
              <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center text-amber-400 group-hover:bg-white/10 transition-all duration-300">
                <Sparkles className="w-5 h-5" />
              </div>
            </div>
            {isOpen[item.id] && (
              <div className="space-y-3 text-stone-400">
                {item.answer.split('\n').map((line, idx) => (
                  <p key={idx} className="first:mt-2">
                    {line}
                  </p>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

.font-display { font-family: 'Playfair Display', Georgia, serif; }
.font-body { font-family: 'Inter', system-ui, sans-serif; }
body { font-family: 'Inter', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

